use crate::{has, lever, tree, write};

const PLANNED: &str = "[case]\ntier = \"push\"\nstatus = \"planned\"\nclaims = [\"correctness\"]\nreference = \"analytic\"\n";
const BEGIN: &str =
    "// cases: begin (generated by `cargo xtask new-case`; `cargo xtask layout` checks it)\n";

fn runner(table: &str) -> String {
    format!(
        "use xtask::harness::{{self, Measure}};\n\n{BEGIN}{table}// cases: end\n\nfn main() {{\n    harness::main(CASES);\n}}\n"
    )
}

#[test]
fn a_source_file_without_a_mirror_or_a_declaration_is_caught() {
    let root = tree(
        "layout-mirror",
        &[
            ("src/lib.rs", ""),
            ("src/a.rs", "pub fn f() {}\n"),
            ("tests/lib.rs", "mod gone;\n"),
            ("tests/gone.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(has(&findings, "src/a.rs has no mirror tests/a.rs"));
    assert!(has(&findings, "orphan test tests/gone.rs"));
    assert!(has(&findings, "src/a.rs is not declared"));
}

#[test]
fn inline_tests_and_items_in_layer_roots_are_caught() {
    let root = tree(
        "layout-inline",
        &[
            ("src/lib.rs", "mod pw;\n"),
            (
                "src/pw.rs",
                "mod basis;\npub fn helper() {}\nmod kinetic {\n    pub(super) fn energy() {}\n}\n",
            ),
            ("src/pw/basis.rs", "#[cfg(test)]\nmod t {}\n"),
            (
                "src/pw/grid.rs",
                "#[cfg(all(unix, test))] // note\nmod t {}\n",
            ),
            ("src/pw/fft.rs", "#[cfg(feature = \"latest\")]\nmod t {}\n"),
            (
                "src/pw/probe.rs",
                "#[rustfmt::skip] #[test] fn miller_probe() {}\n",
            ),
            ("tests/pw/probe.rs", ""),
            ("tests/pw/grid.rs", ""),
            ("tests/pw/fft.rs", ""),
            (
                "src/ks.rs",
                "//! Bands.\nmod bands;\nconst LIMIT: u8 = 1;\n",
            ),
            ("src/ks/bands.rs", ""),
            ("tests/lib.rs", "mod pw;\n"),
            ("tests/pw.rs", "mod basis;\n"),
            ("tests/pw/basis.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(has(&findings, "src/pw/basis.rs:1 holds an inline test"));
    assert!(has(&findings, "src/pw/grid.rs:1 holds an inline test"));
    assert!(has(&findings, "src/pw/probe.rs:1 holds an inline test"));
    assert!(!has(&findings, "src/pw/fft.rs holds"), "{findings:?}");
    assert!(has(&findings, "src/pw.rs:2 holds code"));
    assert!(has(&findings, "src/pw.rs:3 holds code"), "{findings:?}");
    assert!(!has(&findings, "src/pw.rs:1"), "{findings:?}");
    assert!(has(&findings, "src/ks.rs:3 holds code"), "{findings:?}");
    assert!(
        !has(&findings, "src/ks.rs:1"),
        "an inner doc comment is an attribute: {findings:?}"
    );
    assert!(!has(&findings, "src/ks.rs:2"), "{findings:?}");
}

#[test]
fn an_engine_constructor_named_new_is_caught() {
    let root = tree(
        "layout-new",
        &[
            ("src/lib.rs", "mod cell;\n"),
            (
                "src/cell.rs",
                "pub struct Cell(Vec<u8>);\n// fn new\nimpl Cell {\n    pub fn new() -> Self {\n        Cell(Vec::new())\n    }\n}\n",
            ),
            ("tests/lib.rs", "mod cell;\n"),
            ("tests/cell.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(
        has(&findings, "src/cell.rs:4 defines `fn new`"),
        "{findings:?}"
    );
    assert_eq!(
        findings.iter().filter(|f| f.contains("fn new")).count(),
        1,
        "a comment or a call is no definition: {findings:?}"
    );
}

#[test]
fn allow_attributes_are_caught_even_as_inner_attributes() {
    let files = [
        ("src/lib.rs", "#![allow(dead_code, reason = \"x\")]\n"),
        ("tests/lib.rs", "#[allow(unused)]\nfn f() {}\n"),
    ];
    let findings = lever(&["layout"], &tree("layout-allow", &files));
    assert!(has(&findings, "src/lib.rs:1 uses allow"));
    assert!(has(&findings, "tests/lib.rs:1 uses allow"));
}

#[test]
fn a_symlinked_source_is_caught() {
    let root = tree("layout-link", &[("src/lib.rs", ""), ("tests/lib.rs", "")]);
    std::os::unix::fs::symlink("/etc/hostname", root.join("src/alias.rs")).unwrap();
    assert!(has(&lever(&["layout"], &root), "src/alias.rs is a symlink"));
}

#[test]
fn the_case_table_must_match_the_case_directories_exactly() {
    let swapped = "#[path = \"benchmarks/1_a/case.rs\"]\nmod n2_b;\n#[path = \"benchmarks/2_b/case.rs\"]\nmod n1_a;\n\nconst CASES: &[(&str, Measure)] = &[\n    (\"1_a\", n1_a::measure),\n    (\"2_b\", n2_b::measure),\n];\n";
    let root = tree(
        "layout-table",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("benchmarks/2_b/case.toml", PLANNED),
            ("tests/benchmarks/1_a/case.rs", ""),
            ("tests/benchmarks/2_b/case.rs", ""),
            ("tests/benchmarks.rs", &runner(swapped)),
        ],
    );
    assert!(has(
        &lever(&["layout"], &root),
        "the case table in tests/benchmarks.rs differs"
    ));
    write(&root, "tests/benchmarks.rs", "fn main() {}\n");
    assert!(has(
        &lever(&["layout"], &root),
        "lacks the line `// cases: begin"
    ));
}

#[test]
fn new_case_takes_the_next_number_and_regenerates_the_table() {
    let root = tree(
        "layout-new",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("tests/benchmarks/1_a/case.rs", ""),
            ("tests/benchmarks.rs", &runner("")),
        ],
    );
    assert!(has(&lever(&["new-case", "eos", "magic"], &root), "usage"));
    for slug in ["", "Eos", "si-eos"] {
        assert!(
            has(&lever(&["new-case", slug, "analytic"], &root), "usage"),
            "{slug:?}"
        );
    }
    assert!(lever(&["new-case", "si_eos", "all-electron"], &root).is_empty());
    let case = std::fs::read_to_string(root.join("benchmarks/2_si_eos/case.toml")).unwrap();
    assert!(case.contains("reference = \"all-electron\"") && case.contains("planned"));
    let what = std::fs::read_to_string(root.join("benchmarks/results-what.toml")).unwrap();
    assert_eq!(what, "\n[2]\nwhat = \"si eos\"\nmetric = []\nunit = \"\"\n");
    assert!(
        lever(&["layout"], &root).is_empty(),
        "{:?}",
        lever(&["layout"], &root)
    );
    write(&root, "tests/benchmarks.rs", "fn main() {}\n");
    assert!(has(
        &lever(&["new-case", "x", "analytic"], &root),
        "lacks the line"
    ));
    assert!(!root.join("benchmarks/3_x").exists());
}

#[test]
fn a_two_digit_case_keeps_the_table_as_rustfmt_orders_it() {
    let root = tree(
        "layout-two-digits",
        &[
            ("benchmarks/DATASETS.toml", ""),
            ("tests/benchmarks.rs", &runner("")),
        ],
    );
    for slug in ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"] {
        assert!(lever(&["new-case", slug, "analytic"], &root).is_empty());
    }
    let check = std::process::Command::new("rustfmt")
        .args(["--edition", "2024", "--check", "tests/benchmarks.rs"])
        .current_dir(&root)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "{}",
        String::from_utf8_lossy(&check.stdout)
    );
    assert!(lever(&["layout"], &root).is_empty());
}

#[test]
fn each_case_has_both_halves() {
    let root = tree(
        "layout-pairs",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("tests/benchmarks/9_gone/case.rs", ""),
            ("tests/benchmarks.rs", &runner("")),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(has(&findings, "missing tests/benchmarks/1_a/case.rs"));
    assert!(has(
        &findings,
        "orphan tests/benchmarks/9_gone/case.rs (no benchmarks/9_gone/)"
    ));
}

#[test]
fn a_measured_vasp_case_starts_in_the_claim_tier() {
    let root = tree(
        "layout-vasp",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("tests/benchmarks/1_a/case.rs", ""),
            ("tests/benchmarks.rs", &runner("")),
        ],
    );
    assert!(lever(&["new-case", "si_scf_speed", "vasp-measured"], &root).is_empty());
    let case = std::fs::read_to_string(root.join("benchmarks/2_si_scf_speed/case.toml")).unwrap();
    assert!(case.contains("tier = \"claim\""), "{case}");
    assert!(
        case.contains("claims = [\"accuracy\", \"speed\"]"),
        "{case}"
    );
    assert!(
        lever(&["layout"], &root).is_empty(),
        "{:?}",
        lever(&["layout"], &root)
    );
}

#[test]
fn a_parent_must_declare_each_file_by_name() {
    let root = tree(
        "layout-declared",
        &[
            ("src/lib.rs", "mod other;\n"),
            ("src/other.rs", ""),
            ("src/a.rs", "pub fn f() {}\n"),
            ("tests/lib.rs", "mod other;\nmod a;\n"),
            ("tests/other.rs", ""),
            ("tests/a.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(has(&findings, "src/a.rs is not declared"), "{findings:?}");
    assert!(
        !has(&findings, "src/other.rs is not declared"),
        "{findings:?}"
    );
}

#[test]
fn a_layer_root_declares_with_crate_scope_and_reexports_only() {
    let root = tree(
        "layout-roots",
        &[
            ("src/lib.rs", "pub mod pw;\npub(crate) mod ks;\nmod xc;\n"),
            ("src/main.rs", "fn main() {}\n"),
            ("src/notes.txt", "not rust (\n"),
            (
                "src/pw.rs",
                "pub(crate) mod basis;\npub use basis::Basis;\n",
            ),
            ("src/ks.rs", "pub(super) mod bands;\n"),
            ("src/xc.rs", "mod lda;\nuse crate::pw::Basis;\n"),
            ("src/pw/basis.rs", ""),
            ("src/ks/bands.rs", ""),
            ("src/xc/lda.rs", ""),
            ("tests/lib.rs", "mod pw;\nmod ks;\nmod xc;\nmod main;\n"),
            ("tests/main.rs", ""),
            ("tests/pw.rs", "mod basis;\n"),
            ("tests/ks.rs", "mod bands;\n"),
            ("tests/xc.rs", "mod lda;\n"),
            ("tests/pw/basis.rs", ""),
            ("tests/ks/bands.rs", ""),
            ("tests/xc/lda.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(
        has(&findings, "src/ks.rs:1 holds code"),
        "pub(super) is not crate scope: {findings:?}"
    );
    assert!(
        has(&findings, "src/xc.rs:2 holds code"),
        "a private use re-exports nothing: {findings:?}"
    );
    assert!(!has(&findings, "src/pw.rs"), "{findings:?}");
    assert!(!has(&findings, "src/lib.rs"), "{findings:?}");
    assert!(
        !has(&findings, "src/main.rs"),
        "main.rs is code, not a layer root: {findings:?}"
    );
    assert!(!has(&findings, "src/notes.txt"), "{findings:?}");
}

#[test]
fn the_case_table_is_checked_once_a_case_or_a_runner_exists() {
    let empty = lever(
        &["layout"],
        &tree("layout-no-cases", &[("benchmarks/.keep", "")]),
    );
    assert!(!has(&empty, "tests/benchmarks.rs"), "{empty:?}");
    let case = tree(
        "layout-case-no-runner",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("tests/benchmarks/1_a/case.rs", ""),
        ],
    );
    assert!(has(
        &lever(&["layout"], &case),
        "tests/benchmarks.rs lacks the line"
    ));
    let runner = tree(
        "layout-runner-no-case",
        &[
            ("benchmarks/.keep", ""),
            ("tests/benchmarks.rs", &runner("// stale\n")),
        ],
    );
    assert!(has(
        &lever(&["layout"], &runner),
        "the case table in tests/benchmarks.rs differs"
    ));
}

#[test]
fn a_layer_root_item_may_carry_attributes_and_braced_uses() {
    let root = tree(
        "layout-attributes",
        &[
            ("src/lib.rs", "mod pw;\nmod xc;\n"),
            (
                "src/pw.rs",
                "#[cfg(unix)]\nmod basis;\n#[doc(hidden)]\npub use basis::{Basis, lowest};\n",
            ),
            ("src/pw/basis.rs", ""),
            ("src/xc.rs", "mod lda;\n#[inline]\npub fn f() {}\nmod pz\n"),
            ("src/xc/lda.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(!has(&findings, "src/pw.rs:"), "{findings:?}");
    assert!(has(&findings, "src/xc.rs:3 holds code"), "{findings:?}");
    assert!(
        !has(&findings, "src/xc.rs:2"),
        "an attribute is not the item: {findings:?}"
    );
    assert!(
        has(&findings, "src/xc.rs:4 holds code"),
        "an item without its `;` is code: {findings:?}"
    );
}

#[test]
fn only_mod_declares_and_a_cfg_ends_with_its_item() {
    let root = tree(
        "layout-mod-item",
        &[
            ("src/lib.rs", "mod pw;\nmod ks;\n"),
            ("src/pw.rs", "use grid;\n"),
            ("src/pw/grid.rs", ""),
            (
                "src/ks.rs",
                "#[cfg(test)]\nuse std::fmt;\nmod bands;\n#[cfg(unix)]\nfn f() {}\nmod occupations;\n",
            ),
            ("src/ks/bands.rs", ""),
            ("src/ks/occupations.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(
        has(&findings, "src/pw/grid.rs is not declared"),
        "{findings:?}"
    );
    assert!(!has(&findings, "under a cfg"), "{findings:?}");
}

#[test]
fn a_module_hidden_by_cfg_or_a_comment_is_not_declared() {
    let root = tree(
        "layout-cfg-mod",
        &[
            ("src/lib.rs", "mod pw;\nmod ks;\n"),
            ("src/pw.rs", "#[cfg(any())]\nmod grid;\n"),
            ("src/pw/grid.rs", ""),
            ("src/ks.rs", "/*\nmod bands;\n*/\n"),
            ("src/ks/bands.rs", ""),
        ],
    );
    let findings = lever(&["layout"], &root);
    assert!(
        has(
            &findings,
            "src/pw.rs declares `mod grid` under a cfg, which can compile src/pw/grid.rs out"
        ),
        "{findings:?}"
    );
    assert!(
        has(&findings, "src/ks/bands.rs is not declared"),
        "{findings:?}"
    );
}
